*{box-sizing:border-box}
html,body,#root{margin:0;background:#0d1822;color:#e7eef4;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif}
#root{padding:2px}
.big,.ct,.dt,.bid,.pager span{font-variant-numeric:tabular-nums}
.kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:14px}
.tile{background:#1E293B;border:1px solid #26384a;border-radius:12px;padding:16px 18px;display:flex;align-items:flex-end;justify-content:space-between;gap:10px;position:relative;overflow:hidden}
.tile::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--c,#4f93df)}
.tile .lbl{font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:#8ba0b2}
.tile .lbl .hint{display:block;margin-top:4px;font-size:11px;letter-spacing:0;text-transform:none;color:#5f7688}
.tile .big{font-size:34px;font-weight:680;letter-spacing:-.02em;color:var(--c,#4f93df);line-height:1}
.panels{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px}
.panel{background:#15232f;border:1px solid #22384a;border-radius:12px;padding:16px 18px}
.panel h2{font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#8ba0b2;margin:0 0 14px;font-weight:600}
.sender{display:grid;grid-template-columns:130px 1fr 34px;align-items:center;gap:12px;margin-bottom:11px;cursor:default}
.sender .nm{font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bar{height:8px;border-radius:999px;background:#1E293B;overflow:hidden}
.bar>i{display:block;height:100%;border-radius:999px;background:linear-gradient(90deg,#4f93df,#35c98a)}
.sender .ct{text-align:right;font-size:13px;color:#8ba0b2}
.trend{display:flex;align-items:flex-end;gap:8px;height:120px;padding-top:6px}
.trend .col{flex:1;display:flex;flex-direction:column;align-items:center;gap:7px;height:100%;justify-content:flex-end;cursor:default}
.trend .col>span{width:100%;border-radius:5px 5px 0 0;background:linear-gradient(180deg,#4f93df,#2f5f96);min-height:3px;transition:filter .1s}
.trend .col:last-child>span{background:linear-gradient(180deg,#35c98a,#1f7a53)}
.trend .col:hover>span{filter:brightness(1.25)}
.trend .col em{font-style:normal;font-size:10px;color:#5f7688}
.tablecard{background:#15232f;border:1px solid #22384a;border-radius:12px;overflow:hidden}
.toolbar{display:flex;align-items:center;gap:10px;padding:12px 14px;border-bottom:1px solid #22384a}
.search{flex:1;display:flex;align-items:center;gap:8px;background:#0a141d;border:1px solid #26384a;border-radius:9px;padding:8px 12px;color:#8ba0b2}
.search input{border:0;background:transparent;color:#e7eef4;font:inherit;font-size:13px;width:100%;outline:none}
.tbtn{display:inline-flex;align-items:center;gap:6px;font-size:13px;color:#8ba0b2;background:transparent;border:1px solid #26384a;border-radius:9px;padding:8px 12px;cursor:pointer}
.tbtn:hover{color:#e7eef4}
.tscroll{overflow-x:auto}
table{width:100%;border-collapse:collapse;font-size:13px;min-width:820px}
thead th{text-align:left;font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:#5f7688;font-weight:600;padding:11px 16px;background:#182735;border-bottom:1px solid #22384a;white-space:nowrap}
tbody td{padding:12px 16px;border-bottom:1px solid rgba(34,56,74,.55);vertical-align:top}
tbody tr:hover{background:rgba(79,147,223,.06)}
td.dt,td.bid{color:#8ba0b2;white-space:nowrap}
td.cust{font-weight:550;white-space:nowrap}
td.snd .chip{display:inline-block;font-size:12px;background:#1E293B;border:1px solid #26384a;border-radius:999px;padding:2px 9px;white-space:nowrap}
td.msg{color:#8ba0b2;max-width:440px}
td.msg .tag{color:#4f93df}
.empty{padding:22px 16px;text-align:center;color:#5f7688;font-size:13px}
.pager{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:11px 14px;color:#8ba0b2;font-size:13px}
.pg{display:flex;gap:6px}
.pg button{background:#182735;border:1px solid #26384a;color:#8ba0b2;border-radius:7px;min-width:30px;height:30px;cursor:pointer;font:inherit}
.pg button:disabled{opacity:.4;cursor:default}
.tt{position:fixed;z-index:99;pointer-events:none;background:#0a141d;border:1px solid #33475a;color:#e7eef4;font-size:12px;padding:6px 10px;border-radius:8px;box-shadow:0 8px 22px rgba(0,0,0,.45);opacity:0;transition:opacity .1s;white-space:nowrap}
@media(max-width:820px){.kpis,.panels{grid-template-columns:1fr}}
.pg .dots{color:#5f7688;padding:0 4px;align-self:center;font-size:13px}
.pg button.cur{background:#35c98a;border-color:#35c98a;color:#08131b;font-weight:650}
.pg button:not(:disabled):hover{color:#e7eef4;border-color:#3a5064}

