var term = "";
var lastModel = "";
var tt = document.createElement("div"); tt.className = "tt"; document.body.appendChild(tt);
document.addEventListener("mousemove", function(e){
  var el = (e.target && e.target.closest) ? e.target.closest("[data-tip]") : null;
  if(el){ tt.textContent = el.getAttribute("data-tip"); tt.style.opacity = "1"; tt.style.left = (e.clientX + 14) + "px"; tt.style.top = (e.clientY + 16) + "px"; }
  else { tt.style.opacity = "0"; }
});
function esc(s){return String(s==null?"":s).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c];});}
function hl(s){return esc(s).replace(/@[A-Za-z][\w.'-]*(?:\s\([^)]*\))?(?:\s[A-Z][\w.'-]*)*/g,function(x){return '<span class="tag">'+x+'</span>';});}
function goto(page){ var m=(window.appsmith&&appsmith.model)||{}; var ps=m.pageSize||20; appsmith.updateModel({ gotoOffset: Math.max(0,(page-1)*ps) }); appsmith.triggerEvent("onGotoPage"); }
function pageList(cur,pages){ var out=[]; if(pages<=7){ for(var i=1;i<=pages;i++) out.push(i); } else { out.push(1); var lo=Math.max(2,cur-1), hi=Math.min(pages-1,cur+1); if(lo>2) out.push("..."); for(var i=lo;i<=hi;i++) out.push(i); if(hi<pages-1) out.push("..."); out.push(pages);} return out; }
function render(){
  var m=(window.appsmith&&appsmith.model)||{};
  var st=m.stats||{total:0,last_30:0,last_7:0};
  var senders=m.topSenders||[];
  var maxS=Math.max.apply(null,[1].concat(senders.map(function(s){return s.n||0;})));
  var trend=m.trend||[];
  var maxT=Math.max.apply(null,[1].concat(trend.map(function(t){return t.n||0;})));
  var allRows=m.rows||[];
  var total=m.total||0, offset=m.offset||0, pageSize=m.pageSize||20;
  var rows=allRows;
  if(term){var t=term.toLowerCase();rows=allRows.filter(function(r){return (String(r.customer)+" "+r.sender+" "+r.message+" "+r.bill_id).toLowerCase().indexOf(t)>=0;});}
  var from=total?offset+1:0, to=offset+allRows.length;
  var cur=Math.floor(offset/pageSize)+1, pages=Math.max(1,Math.ceil(total/pageSize));
  function tile(label,hint,val,color){return '<div class="tile" style="--c:'+color+'"><span class="lbl">'+label+(hint?'<span class="hint">'+hint+'</span>':'')+'</span><span class="big">'+(val||0)+'</span></div>';}
  var kpis=tile("Total","All time",st.total,"#4f93df")+tile("Last 30 days","",st.last_30,"#35c98a")+tile("Last 7 days","",st.last_7,"#e2a53c");
  var sHtml=senders.length?senders.map(function(s){return '<div class="sender" data-tip="'+esc(s.sender)+' · '+s.n+' notifications"><span class="nm">'+esc(s.sender)+'</span><span class="bar"><i style="width:'+Math.round((s.n/maxS)*100)+'%"></i></span><span class="ct">'+s.n+'</span></div>';}).join(""):'<div class="empty">No senders in range</div>';
  var tHtml=trend.length?trend.map(function(x){return '<div class="col" data-tip="Week of '+esc(x.wk)+' · '+x.n+' notifications"><span style="height:'+Math.max(3,Math.round((x.n/maxT)*100))+'%"></span><em>'+esc(x.wk)+'</em></div>';}).join(""):'<div class="empty">No data</div>';
  var tb=rows.length?rows.map(function(r){return '<tr><td class="dt">'+esc(r.date_time)+'</td><td class="cust">'+esc(r.customer)+'</td><td class="bid">'+esc(r.bill_id)+'</td><td class="snd"><span class="chip">'+esc(r.sender)+'</span></td><td class="msg">'+hl(r.message)+'</td></tr>';}).join(""):'<tr><td colspan="5" class="empty">No notifications for the selected filters.</td></tr>';
  var nums=pageList(cur,pages).map(function(p){ return p==="..." ? '<span class="dots">…</span>' : '<button data-page="'+p+'"'+(p===cur?' class="cur"':'')+'>'+p+'</button>'; }).join("");
  var pager='<div class="pg"><button data-page="'+(cur-1)+'"'+(cur<=1?' disabled':'')+'>‹</button>'+nums+'<button data-page="'+(cur+1)+'"'+(cur>=pages?' disabled':'')+'>›</button></div>';
  document.getElementById("root").innerHTML=
    '<div class="kpis">'+kpis+'</div>'+
    '<div class="panels"><div class="panel"><h2>Who tags this user most</h2>'+sHtml+'</div><div class="panel"><h2>Notifications over time · last 8 weeks</h2><div class="trend">'+tHtml+'</div></div></div>'+
    '<div class="tablecard"><div class="toolbar"><div class="search"><span>⌕</span><input id="q" placeholder="Search messages, senders, bills…" value="'+esc(term)+'"></div><button class="tbtn" id="dl">↓ Download</button></div>'+
    '<div class="tscroll"><table><thead><tr><th>Date &amp; Time</th><th>Customer</th><th>Bill ID</th><th>Sender</th><th>Message</th></tr></thead><tbody>'+tb+'</tbody></table></div>'+
    '<div class="pager"><span>'+(total?("Showing "+from+"–"+to+" of "+total):"No records")+'</span>'+pager+'</div></div>';
  var q=document.getElementById("q");
  if(q){q.addEventListener("input",function(e){term=e.target.value;render();var nq=document.getElementById("q");if(nq){nq.focus();nq.setSelectionRange(nq.value.length,nq.value.length);}});}
  Array.prototype.forEach.call(document.querySelectorAll(".pg button[data-page]"),function(b){ b.addEventListener("click",function(){ var pg=parseInt(b.getAttribute("data-page"),10); if(!isNaN(pg)) goto(pg); }); });
  var dl=document.getElementById("dl");if(dl)dl.addEventListener("click",function(){appsmith.triggerEvent("onDownload");});
}
function tick(){try{var s=JSON.stringify((window.appsmith&&appsmith.model)||{});if(s!==lastModel){lastModel=s;render();}}catch(e){}}
render();setInterval(tick,400);

